insert into units (id,phase_id,ord,name,theme,can_do) values
  ('u1','c2p1',1,'Greetings, Time, and Pronouns','Basic Social Encounters','I can greet people at any time of day and use basic pronouns.'),
  ('u2','c2p1',2,'Family, Respect, and Pointers','Basic Locations and Relatives','I can address extended family and pinpoint locations.'),
  ('u3','c2p1',3,'House and Daily Actions','Home Environment in Daram','I can identify house parts and express basic daily actions.'),
  ('u4','c2p1',4,'Food, Drinks, and Requests','Staple Needs and Politeness','I can ask for specific foods and make polite requests.'),
  ('u5','c2p1',5,'Numbers and Money','Small Market Transactions','I can count up to ten and handle basic transactions.'),
  ('u6','c2p2',1,'Meeting the In-Laws','Extended family introductions and respect','Introduce yourself respectfully to extended family members.'),
  ('u7','c2p2',2,'Everyday Objects in the Yard','Household items and chores','Ask for common household items outside or in the kitchen.'),
  ('u8','c2p2',3,'Where are You Going? (Kain ka?)','Neighborhood greetings and daily activities','Answer the common neighborhood passing greeting.'),
  ('u9','c2p2',4,'Talking About the Weather','Weather and daily life','Comment on the heat, rain, and wind with community members.'),
  ('u10','c2p2',5,'Time of Day and Simple Tasks','Daily routines and coordinating activities in a rural island setting.','Coordinate basic daily times for chores or casual meetings.'),
  ('u11','c2p2',6,'Phase 2 Review & Celebration','A small neighborhood celebration with food and friends.','Combine early neighborhood conversations smoothly.');
