insert into expressions (id,waray,translation,focus) values
  (1,'Maupay nga aga, hi Maria.','Good morning, Maria.',null),
  (2,'Kamusta ka yana?','How are you now?',null),
  (3,'Maupay ako yana.','I am good now.',null),
  (4,'Maupay hira kanina.','They were good earlier.',null),
  (5,'Maupay kita niyan!','We''ll be good later (you and I)!',null),
  (6,'Maupay nga gab-i, hi Juan.','Good evening, Juan.',null),
  (7,'Kamusta hira? Maupay kami.','How are they? We''re good (not you).',null),
  (8,'Maupay kita yana.','We are good now (you and I).',null),
  (9,'Maupay nga aga. Ako hi Maria.','Good morning. I am Maria.',null),
  (10,'Maupay ako. Maupay kita yana!','I am good. We are good now!',null),
  (11,'Hain hi tatay mo?','Where is your father?',null),
  (12,'Aadi hi nanay.','Mother is here.',null),
  (13,'Aada hi kuya.','Older brother is there.',null),
  (14,'Didto hi ate.','Older sister is over there.',null),
  (15,'Diri hiya an bugto ko.','He/she is not my sibling.',null),
  (16,'Oo, dadi hi anak ko.','Yes, my child, come here.',null),
  (17,'Hain hi asawa mo?','Where is your spouse?',null),
  (18,'Diri hiya aadi, ngadto hiya.','He/she is not here, he/she goes there.',null),
  (19,'Aada hi apo ko, dadi!','My grandchild is there, come here!',null),
  (20,'Oo, hi nanay ko aadi.','Yes, my mother is here.',null),
  (21,'Aadi ako ha Daram.','I am here in Daram.',null),
  (22,'Hain hi nanay ko?','Where is my mother?',null),
  (23,'Aada hi nanay ko. Dadi!','My mother is there. Come here!',null),
  (24,'Didto hi tatay ko ngan hi apo ko.','My father and my grandchild are over there.',null),
  (25,'Sulod ha kwarto.','Enter the room.',null),
  (26,'Lingkod ha pantaw.','Sit on the back porch.',null),
  (27,'Imo balay ini.','This is your house.',null),
  (28,'Gawas ha natad.','Go out to the yard.',null),
  (29,'Akon kusina adto.','That is my kitchen.',null),
  (30,'Tindog ha purtahan.','Stand at the door.',null),
  (31,'Iyo bintana adto.','That is your (plural) window.',null),
  (32,'Aadi in kudal.','Here is the fence.',null),
  (33,'Sulod ha balay, akon anak.','Come in, my child.',null),
  (34,'Maupay nga aga! Ini in akon balay.','Good day! This is my house.',null),
  (35,'Sulod ha purtahan, tapos lingkod ha pantaw.','Enter the door, then sit on the back porch.',null),
  (36,'Adto in iyo kwarto, ngan didto in akon kusina.','That is your (plural) room, and there is my kitchen.',null),
  (37,'Gawas ha natad, in kudal didto.','Go out to the yard, there is a fence there.',null),
  (38,'Gusto ko hin init nga kape.','I want some hot coffee.',null),
  (39,'Kinahanglan ko hin tubig, alayon.','I need some water, please.',null),
  (40,'Kaon hin isda ngan utan.','Eat some fish and vegetables.',null),
  (41,'Gusto mo matugnaw nga prutas?','Do you want cold fruit?',null),
  (42,'Inom sin sabaw.','Drink some soup.',null),
  (43,'Salamat, gusto ko hin kan-on.','Thank you, I want some rice.',null),
  (44,'Alayon, gusto ko hin tinapay.','Please, I want some bread.',null),
  (45,'Kinahanglan mo ba matugnaw nga tubig?','Do you need cold water?',null),
  (46,'Kaon hin prutas ngan inom hin tubig.','Eat fruit and drink water.',null),
  (47,'Hi Lolo Ben gusto hin kape.','Grandpa Ben wants coffee.',null),
  (48,'Kinahanglan niya hin kan-on ngan isda.','He needs some rice and fish.',null),
  (49,'Alayon, gusto niya matugnaw nga tubig.','Please, he wants cold water.',null),
  (50,'Salamat, Lolo Ben maupay.','Thank you, Grandpa Ben is happy.',null),
  (51,'Tagpira ini nga isda?','How much is this fish?',null),
  (52,'Lima ka pesos.','Five pesos.',null),
  (53,'Mapalit ako tulo ka isda.','I will buy three fish.',null),
  (54,'Mahal ini.','This is expensive.',null),
  (55,'Barato an tinapay.','The bread is cheap.',null),
  (56,'Waray ako sukli.','I don''t have change.',null),
  (57,'Pira an kwarta mo?','How much money do you have?',null),
  (58,'Mapalit ka napulo ka tinapay?','Will you buy ten breads?',null),
  (59,'Bayad na! Waray sukli.','Pay now! No change.',null),
  (60,'Mahal an isda, barato an tinapay.','The fish is expensive, the bread is cheap.',null),
  (61,'Mapalit ako isda.','I will buy fish.',null),
  (62,'Tagpira ini?','How much is this?',null),
  (63,'Mahal an isda. Barato an tinapay.','The fish is expensive. The bread is cheap.',null),
  (64,'Maupay nga gab-i, lolo.','Good evening, grandfather.',null),
  (65,'Hiya an akon ugangan.','She is my parent-in-law.',null),
  (66,'Kita malipayon nga pamilya.','We are a happy family.',null),
  (67,'An imo tiyo buotan.','Your uncle is kind.',null),
  (68,'Salamat, tiya, kaupod kami.','Thank you, aunt, we are companions.',null),
  (69,'Dayaw ko an imo hipag.','I admire your sister-in-law.',null),
  (70,'Kamusta, lola.','How are you, grandmother.',null),
  (71,'Hiya an akon bayaw.','He is my brother-in-law.',null),
  (72,'Aadi an imo umangkon.','Your niece/nephew is here.',null),
  (73,'Kita bisita yana.','We are guests today.',null),
  (74,'Yana, hi Ana ngan hi Ben bisita ha balay ni lola.','Today, Ana and Ben are guests at grandmother''s house.',null),
  (75,'Aadi hi tiyo, hi tiya, ngan hi bayaw ni Ana.','Here are Ana''s uncle, aunt, and brother-in-law.',null),
  (76,'Malipayon an pamilya ni Ana. Buotan hi lola.','Ana''s family is happy. Grandmother is kind.',null),
  (77,'Dayaw ni Ben an kaupod.','Ben praises the companion.',null),
  (78,'Alayon, hain an silhig?','Please, where is the broom?',null),
  (79,'Kinahanglan ko usa nga balde.','I need one bucket.',null),
  (80,'Gusto mo an sulo didto?','Do you want the torch over there?',null),
