  (82,'Aadi an kutsara ngan tinidor.','Here are the spoon and fork.',null),
  (83,'Pira nga kaldero an imo?','How many cooking pots are yours?',null),
  (84,'Laba kita yana, nanay.','Let''s wash clothes now, mother.',null),
  (85,'Hain an kutsilyo ni tatay?','Where is father''s knife?',null),
  (86,'Aadi an imo pwesto.','Here is your spot.',null),
  (87,'Salamat, gusto ko an kape.','Thank you, I want the coffee.',null),
  (88,'Maupay nga aga, lolo. Hain an balde?','Good morning, grandfather. Where is the bucket?',null),
  (89,'Aada an balde, apo. Kinahanglan mo an silhig?','The bucket is over there, grandchild. Do you need the broom?',null),
  (90,'Oo, lolo. Gusto ko maghugas hin pinggan ngan baso.','Yes, grandfather. I want to wash plates and glasses.',null),
  (91,'Dayaw, apo! Pagkaon kamo han isda ngan kan-on.','Good job, grandchild! Eat the fish and rice.',null),
  (92,'Kain ka?','Where are you going?',null),
  (93,'Pakadto ako ha merkado.','I am going to the market.',null),
  (94,'Tikang ako ha simbahan.','I am coming from the church.',null),
  (95,'Trabaho hiya yana.','He/She is working now.',null),
  (96,'Balik ako dayon ha balay.','I will return home right away.',null),
  (97,'Limpyo an balay.','The house is clean.',null),
  (98,'Kain ka pakadto?','Where are you going (to)?',null),
  (99,'Pakadto ako ha eskwelahan.','I am going to the school.',null),
  (100,'Kinahanglan ko trabaho.','I need work (or: I need to work).',null),
  (101,'Pahulay kita ha balay.','Let''s rest at home.',null),
  (102,'Maupay nga aga, Lolo! Kain ka?','Good morning, Grandpa! Where are you going?',null),
  (103,'Pakadto ako ha merkado. Mapalit ako isda ngan utan.','I am going to the market. I will buy fish and vegetables.',null),
  (104,'Tikang ha merkado, pakadto hiya ha tiangge. Nagpalit hiya tinapay.','From the market, he went to the small store. He bought bread.',null),
  (105,'Didto ha balay, kinahanglan niya pahulay dayon. Limpyo an balay ni Lola.','At home, he needed to rest right away. Lola''s house is clean.',null),
  (106,'Init gud an panahon yana.','The weather is really hot now.',null),
  (107,'Nag-uuran na. Basa an natad.','It''s raining already. The yard is wet.',null),
  (108,'Makusog an hangin. Mahangin gud.','The wind is strong. It''s really windy.',null),
  (109,'Masirak yana. Maupay para laba.','It''s sunny now. Good for laundry.',null),
  (110,'Madampog yana. Waray sirak.','It''s cloudy now. No sunshine.',null),
  (111,'Dako nga bagyo an pakadto Daram.','A big typhoon is coming to Daram.',null),
  (112,'Kamusta an panahon ha Daram?','How''s the weather in Daram?',null),
  (113,'Pirmi ba init didto?','Is it always hot there?',null),
  (114,'Unina, nag-uuran na.','Later, it will be raining.',null),
  (115,'Kinahanglan uga an balay tikang ha baha.','The house needs to be dry from the flood.',null),
  (116,'Maupay nga aga! Init an panahon yana.','Good morning! The weather is hot now.',null),
  (117,'Kaina, nag-uuran hin makusog. Basa an natad.','Earlier, it rained strong. The yard is wet.',null),
  (118,'Pero yana, masirak na. Maupay para laba.','But now, it''s sunny already. Good for laundry.',null),
  (119,'Alas sais ako mabangon buwas.','I will wake up at six tomorrow.',null),
  (120,'Tapos na an trabaho ko yana.','My work is finished now.',null),
  (121,'Sayu ka magluto hin isda.','You cook fish early.',null),
  (122,'Magkita kita ha merkado alas tres.','Let''s meet at the market at three o''clock.',null),
  (123,'Urhi hiya bumalik tikang ha balay.','He returned late from the house.',null),
  (124,'Hatag kape, alayon.','Give coffee, please.',null),
  (125,'Pira ka oras ka mapasyada?','How many hours will you stroll?',null),
  (126,'Kagab-i kami nagluto utan.','Last night we cooked vegetables.',null),
  (127,'Sunod nga adlaw, sugod kita paglimpyo.','Next day, let''s start cleaning.',null),
  (128,'Kuha hin tubig, Nanay.','Get water, Mom.',null),
  (129,'Alas singko, sayu bumangon hi Nanay. Nagluto hiya kape ngan kan-on para ha pamilya.','At five o''clock, Mom woke up early. She cooked coffee and rice for the family.',null),
  (130,'Pagkatapos, nagpasyada hiya ha natad. Limpyo an ira balay pirmi.','Afterwards, she strolled in the yard. Their house is always clean.',null),
  (131,'Buwas, magkita hira ni Tatay ha merkado para magpalit isda.','Tomorrow, she and Dad will meet at the market to buy fish.',null),
  (132,'Maupay nga aga! Kamusta ka?','Good morning! How are you?',null),
  (133,'Gusto mo ba kape?','Do you want coffee?',null),
  (134,'Alayon, lingkod didto.','Please, sit there.',null),
  (135,'Kami malipayon nga ikaw bisita.','We are happy that you are a visitor.',null),
  (136,'An kan-on malinamnam!','The rice is delicious!',null),
  (137,'An isda init ngan malinamnam.','The fish is hot and delicious.',null),
  (138,'Gusto mo ba sabaw?','Do you want soup?',null),
  (139,'Salamat ha imo!','Thank you to you!',null),
  (140,'Hatag ko ha imo an prutas.','I give the fruit to you.',null),
  (141,'Nag-uuran yana. Buwas masirak.','It''s raining now. Tomorrow it will be sunny.',null),
  (142,'Pira an oras yana?','What time is it now?',null),
  (143,'Malipayon ako didto ha Daram.','I am happy there in Daram.',null),
  (144,'An trabaho tapos.','The work is finished.',null),
  (145,'Hatag ko ha imo an regalo.','I give the gift to you.',null),
  (146,'Maupay nga kulop! Dayon ha balay ni Nanay.','Good afternoon! Come in to Nanay''s house.',null),
  (147,'Hi Nanay ngan hi Lola nagluto hin kan-on ngan isda. An isda malinamnam!','Nanay and Lola cooked rice and fish. The fish is delicious!',null),
  (148,'Kami malipayon nga ikaw kaupod.','We are happy that you are a companion.',null),
  (149,'Gusto mo ba tubig? Gusto mo ba kape? Aadi an prutas.','Do you want water? Do you want coffee? Here is the fruit.',null);
